  const dueIdx = lines.findIndex(l => l.startsWith('Due:'));
  const paidIdx = lines.findIndex(l => l.startsWith('Paid:'));

  assert.ok(subtotalIdx < discountIdx);
  assert.ok(discountIdx < vatIdx);
  assert.ok(vatIdx < voucherIdx);
  assert.ok(voucherIdx < totalIdx);
  assert.ok(totalIdx < dueIdx);
  assert.ok(dueIdx < paidIdx);
});

test('renderInvoiceText with line discount, bulk discount, voucher, due date, and payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 10, name: 'Item', unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 500 },
    payments: [{ amount: 4000, date: '2026-10-15' }],
  };
  const text = renderInvoiceText(invoice);
  // 10 units triggers bulk discount (2.5% after line discount)
  assert.match(text, /\(-5%\)/);
  assert.match(text, /Discount:/);
  assert.match(text, /Voucher: -€5\.00/);
  assert.match(text, /Due: 2026-11-07/);
  assert.match(text, /Paid: €40\.00/);
});

test('renderInvoiceText with voucher and due date but no line discount or payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 1, name: 'Item', unitPrice: 10000, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 2000 },
  };
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /\(-\d+%\)/);
  assert.match(text, /Voucher: -€20\.00/);
  assert.match(text, /Due: 2026-11-07/);
  assert.doesNotMatch(text, /Paid:/);
});

test('renderInvoiceText with payments and due date but no line discount or voucher', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 1, name: 'Item', unitPrice: 10000, vatRate: 21 }],
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };
  const text = renderInvoiceText(invoice);
  assert.doesNotMatch(text, /\(-\d+%\)/);
  assert.doesNotMatch(text, /Voucher:/);
  assert.match(text, /Due: 2026-11-07/);
  assert.match(text, /Paid: €50\.00/);
});

test('renderInvoiceText with line discount and bulk discount on 10+ units', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ qty: 15, name: 'Item', unitPrice: 1000, discountPercent: 5, vatRate: 21 }],
  };
  const text = renderInvoiceText(invoice);
  // Line shows 5% discount
  assert.match(text, /\(-5%\)/);
  // Total discount includes both line discount (5%) and bulk discount (2.5% of remainder)
  const totals = invoiceTotals(invoice);
  assert.ok(totals.discount > 0);
});

