  assert.ok(totalIndex >= 0);
  assert.ok(vatIndex < totalIndex);
});

// Line discount display tests
test('renderInvoiceText shows line discount as (-X%)', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 Design work \(hour\) €85\.00 €170\.00 \(-10%\)/);
});

test('renderInvoiceText shows multiple line discounts separately', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 1, discountPercent: 5 },
    ],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 Design work \(hour\) €85\.00 €170\.00 \(-10%\)/);
  assert.match(text, /1 Development \(hour\) €120\.00 €120\.00 \(-5%\)/);
});

test('renderInvoiceText does not show discount suffix for lines without discountPercent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 Design work \(hour\) €85\.00 €170\.00\n/);
});

test('renderInvoiceText does not show discount suffix when discountPercent is 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 0 }],
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /(-0%)/);
});

test('renderInvoiceText shows line discount for tier-based discounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  const text = renderInvoiceText(r.value);
  // STICKER is gold tier, 5% discount
  assert.match(text, /\(-5%\)/);
});

test('renderInvoiceText shows line discount for bulk discount (10+ units)', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const text = renderInvoiceText(r.value);
  // With 10+ units, bulk discount is applied (2.5%) in totals
  // but line itself shows 0% as discountPercent
  // The discount is accumulated in the total discount line
  const totals = invoiceTotals(r.value);
  assert.ok(totals.discount > 0);
});

// Voucher display tests
test('renderInvoiceText shows voucher line with amount before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const voucherResult = applyVoucher(r.value, { code: 'TEST-10', amount: 1000 }, []);
  const text = renderInvoiceText(voucherResult.value);
  assert.match(text, /Voucher: -€10\.00/);
});

test('renderInvoiceText shows voucher line before total line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const voucherResult = applyVoucher(r.value, { code: 'TEST-10', amount: 1000 }, []);
  const text = voucherResult.value;
  const rendered = renderInvoiceText(text);
  const lines = rendered.split('\n');
  const voucherIndex = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  assert.ok(voucherIndex >= 0);
  assert.ok(totalIndex >= 0);
  assert.ok(voucherIndex < totalIndex);
});

test('renderInvoiceText does not show voucher line when voucher is absent', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /Voucher:/);
});

test('renderInvoiceText does not show voucher line when voucher amount is zero', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
    voucher: { code: 'ZERO', amount: 0 },
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /Voucher:/);
});

test('renderInvoiceText formats voucher amount correctly through formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const voucherResult = applyVoucher(r.value, { code: 'TEST', amount: 5550 }, []);
  const text = renderInvoiceText(voucherResult.value);
  assert.match(text, /Voucher: -€55\.50/);
});

// Due date display tests
test('renderInvoiceText shows due date when present', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 1, name: 'Item', unitPrice: 1000 }],
  };
  const text = renderInvoiceText(invoice);
  assert.match(text, /Due: 2026-11-07/);
});

test('renderInvoiceText shows due date on its own line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 1, name: 'Item', unitPrice: 1000 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const dueLine = lines.find(l => l.startsWith('Due:'));
  assert.equal(dueLine, 'Due: 2026-11-07');
});

test('renderInvoiceText shows due date after total line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 1, name: 'Item', unitPrice: 1000 }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const totalIndex = lines.findIndex(l => l.startsWith('Total:'));
  const dueIndex = lines.findIndex(l => l.startsWith('Due:'));
  assert.ok(dueIndex > totalIndex);
});

test('renderInvoiceText does not show due date when not present', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.doesNotMatch(text, /Due:/);
});

test('renderInvoiceText handles various due date formats', () => {
  const invoice = {
    customerId: 'C-001',
