import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for draft invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /^DRAFT\n/);
});

test('renderInvoiceText shows invoice number for issued invoices', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r2 = issueInvoice(r.value, []);
  const text = renderInvoiceText(r2.value);
  assert.match(text, /^INV-2026-0001\n/);
});

test('renderInvoiceText shows customer name on second line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows line item with qty, name, unitPrice and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 Design work \(hour\) €85\.00 €170\.00/);
});

test('renderInvoiceText shows multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /2 Design work \(hour\)/);
  assert.match(text, /1 Development \(hour\)/);
});

test('renderInvoiceText calculates total with subtotal, discount, VAT and total lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
    ],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Subtotal:/);
  assert.match(text, /Discount:/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText formats all amounts through formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 1 }],
  });
  const text = renderInvoiceText(r.value);
  // LOGO-PACK: 120000 cents = €1,200.00, standard tier (0% discount), VAT 21%
  // Subtotal: €1,200.00, Discount: €0.00, VAT: €252.00, Total: €1,452.00
  assert.match(text, /€1,200\.00/);
  assert.match(text, /Subtotal:/);
  assert.match(text, /VAT:/);
  assert.match(text, /Total:/);
});

test('renderInvoiceText uses customer name from lookup', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 50 }],
  });
  const text = renderInvoiceText(r.value);
  assert.match(text, /Kite & Co/);
});

test('renderInvoiceText shows subtotal, discount, VAT and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  });
  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');
  const subtotalLine = lines.find(l => l.startsWith('Subtotal:'));
  const discountLine = lines.find(l => l.startsWith('Discount:'));
  const vatLine = lines.find(l => l.startsWith('VAT:'));
  const totalLine = lines.find(l => l.startsWith('Total:'));
  assert.ok(subtotalLine);
  assert.ok(discountLine);
  assert.ok(vatLine);
  assert.ok(totalLine);
});

test('renderInvoiceText does not show discount line when discount is zero', () => {
