test('renderInvoiceText preserves order: subtotal, discount, VAT, voucher, total, due, paid', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
    lines: [{ qty: 2, name: 'Item', unitPrice: 5000, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'TEST', amount: 1000 },
    payments: [{ amount: 5000, date: '2026-10-15' }],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const subtotalIdx = lines.findIndex(l => l.startsWith('Subtotal:'));
  const discountIdx = lines.findIndex(l => l.startsWith('Discount:'));
  const vatIdx = lines.findIndex(l => l.startsWith('VAT:'));
  const voucherIdx = lines.findIndex(l => l.startsWith('Voucher:'));
  const totalIdx = lines.findIndex(l => l.startsWith('Total:'));
  const dueIdx = lines.findIndex(l => l.startsWith('Due:'));
  const paidIdx = lines.findIndex(l => l.startsWith('Paid:'));

  assert.ok(subtotalIdx < discountIdx);
  assert.ok(discountIdx < vatIdx);
  assert.ok(vatIdx < voucherIdx);
  assert.ok(voucherIdx < totalIdx);
  assert.ok(totalIdx < dueIdx);
  assert.ok(dueIdx < paidIdx);
});

test('renderInvoiceText with line discount, bulk discount, voucher, due date, and payments', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    dueDate: '2026-11-07',
